<script>
(function(){
  "use strict";

  var state = {
    objections: []
  };

  var fixLibrary = [
    {
      dim:"proof",
      title:"Build a proof stack above the CTA",
      why:"The buyer needs evidence before they believe the promise.",
      action:"Add 3 proof points: one testimonial, one specific result, and one credibility marker such as years served, certifications, photos, reviews, or case examples.",
      sentence:"Add a compact proof stack near the CTA so the buyer sees evidence before deciding."
    },
    {
      dim:"proof",
      title:"Replace vague claims with observable outcomes",
      why:"Generic claims feel interchangeable and invite comparison shopping.",
      action:"Rewrite the main promise with a measurable or visible result. Use a before/after, timeframe, saved hassle, avoided cost, or concrete deliverable.",
      sentence:"Rewrite the offer promise around a visible result instead of a broad quality claim."
    },
    {
      dim:"price",
      title:"Reframe price as scope plus outcome",
      why:"Price pushback often means the buyer does not understand what is included or why it matters.",
      action:"List exactly what the buyer gets, what problem it prevents, and what the next best alternative costs in time, money, or stress.",
      sentence:"Show what is included and connect the price to the avoided cost or desired outcome."
    },
    {
      dim:"price",
      title:"Add a simple tier or anchor",
      why:"One naked price can feel expensive because the buyer has no frame of reference.",
      action:"Create a basic, standard, and premium version, or compare the offer to the cost of delaying, repairing later, replacing later, or losing time.",
      sentence:"Give buyers a price anchor so the main offer feels easier to evaluate."
    },
    {
      dim:"urgency",
      title:"Create a real reason to act now",
      why:"If waiting feels safe, the buyer will delay even when the offer is good.",
      action:"Add an honest deadline, limited capacity, seasonal reason, expiring bonus, next available start date, or cost-of-delay explanation.",
      sentence:"Add a legitimate urgency reason that explains why waiting creates a downside."
    },
    {
      dim:"urgency",
      title:"Strengthen the CTA into one next step",
      why:"A soft CTA makes the buyer decide too much at once.",
      action:"Change the CTA to one clear action: book a call, request a quote, reserve a spot, send photos, or pick a time. Tell them what happens after clicking.",
      sentence:"Make the CTA specific and explain the next step after the click."
    },
    {
      dim:"risk",
      title:"Lower the perceived risk",
      why:"Buyers hesitate when they fear wasting money, being trapped, or choosing the wrong provider.",
      action:"Add a guarantee, inspection-first option, deposit option, cancellation note, clear timeline, no-pressure quote, or satisfaction policy.",
      sentence:"Add risk reversal so the buyer feels safe taking the first step."
    },
    {
      dim:"risk",
      title:"Preview the process",
      why:"Unclear process creates hidden risk because the buyer does not know what happens next.",
      action:"Add a 3-step process: request, review, result. Include timing, who contacts them, what they need to provide, and when payment happens.",
      sentence:"Show a simple process preview so the buyer knows exactly what happens next."
    },
    {
      dim:"clarity",
      title:"Write a one-sentence offer promise",
      why:"If the offer is hard to summarize, buyers will not remember it or repeat it.",
      action:"Use this shape: We help [buyer] get [specific result] without [main pain] through [service/product].",
      sentence:"Condense the offer into one sentence that names the buyer, result, pain, and mechanism."
    },
    {
      dim:"clarity",
      title:"Cut secondary details from the first screen",
      why:"Too many details early can hide the actual reason to buy.",
      action:"Keep the first screen to buyer, result, proof, price cue, and CTA. Move edge-case details lower.",
      sentence:"Simplify the first screen so the main promise and CTA are impossible to miss."
    },
    {
      dim:"objection",
      title:"Answer the top objection before it appears",
      why:"Repeated objections are conversion leaks, not random feedback.",
      action:"Add a short objection block near the offer: If you are wondering about [objection], here is the direct answer.",
      sentence:"Add a direct objection answer near the offer instead of waiting for buyers to ask."
    },
    {
      dim:"objection",
      title:"Add a comparison note",
      why:"When buyers compare you to cheaper or broader alternatives, they need a clear distinction.",
      action:"Explain who this is best for, who it is not for, and what makes the offer different from a cheaper option.",
      sentence:"Add a comparison note that clarifies why this offer is different from the cheaper alternative."
    }
  ];

  var els = {
    business: document.getElementById("business"),
    audience: document.getElementById("audience"),
    offer: document.getElementById("offer"),
    price: document.getElementById("price"),
    cta: document.getElementById("cta"),
    objectionInput: document.getElementById("objectionInput"),
    objectionList: document.getElementById("objectionList"),
    fixList: document.getElementById("fixList"),
    planBox: document.getElementById("planBox"),
    diagnosis: document.getElementById("diagnosis"),
    healthNum: document.getElementById("healthNum"),
    riskNum: document.getElementById("riskNum"),
    fixNum: document.getElementById("fixNum"),
    objectionNum: document.getElementById("objectionNum"),
    proof: document.getElementById("proof"),
    priceFit: document.getElementById("priceFit"),
    urgency: document.getElementById("urgency"),
    risk: document.getElementById("risk"),
    proofVal: document.getElementById("proofVal"),
    priceFitVal: document.getElementById("priceFitVal"),
    urgencyVal: document.getElementById("urgencyVal"),
    riskVal: document.getElementById("riskVal"),
    toast: document.getElementById("toast")
  };

  function val(id){
    return document.getElementById(id).value.trim();
  }

  function num(el){
    return parseInt(el.value,10) || 0;
  }

  function selectedSymptoms(){
    return Array.prototype.slice.call(document.querySelectorAll("#symptomChips input:checked")).map(function(input){
      return { value: input.value, dim: input.getAttribute("data-dim") || "clarity" };
    });
  }

  function objectionDims(){
    var text = state.objections.join(" ").toLowerCase();
    var dims = [];
    if(/expensive|price|cost|budget|cheaper|discount|afford/.test(text)) dims.push("price");
    if(/trust|proof|review|testimonial|results|work|legit|scam|know/.test(text)) dims.push("proof");
    if(/later|think|ready|time|now|wait|soon|urgent/.test(text)) dims.push("urgency");
    if(/guarantee|refund|contract|cancel|risk|safe|mistake|waste/.test(text)) dims.push("risk");
    if(/compare|competitor|different|why you|why this|included/.test(text)) dims.push("objection");
    return dims;
  }

  function dimensionPressure(){
    var proof = 6 - num(els.proof);
    var price = 6 - num(els.priceFit);
    var urgency = 6 - num(els.urgency);
    var risk = num(els.risk);
    var clarity = 2;
    var objection = Math.min(5, state.objections.length + 1);

    selectedSymptoms().forEach(function(s){
      if(s.dim === "proof") proof += 1.2;
      if(s.dim === "price") price += 1.2;
      if(s.dim === "urgency") urgency += 1.2;
      if(s.dim === "risk") risk += 1.2;
      if(s.dim === "clarity") clarity += 1.2;
    });

    objectionDims().forEach(function(d){
      if(d === "proof") proof += 1.1;
      if(d === "price") price += 1.1;
      if(d === "urgency") urgency += 1.1;
      if(d === "risk") risk += 1.1;
      if(d === "objection") objection += 1.1;
    });

    var offerText = [val("offer"), val("price"), val("cta")].join(" ").toLowerCase();
    if(!/(review|testimonial|case|proof|result|rated|before|after|certified|licensed)/.test(offerText)) proof += .8;
    if(!val("price")) price += .6;
    if(!/(today|now|deadline|limited|until|season|spots|book|reserve)/.test(offerText)) urgency += .8;
    if(!/(guarantee|refund|cancel|no pressure|free quote|inspection|trial|deposit)/.test(offerText)) risk += .7;
    if(val("offer").length < 80) clarity += .8;

    return {
      proof: Math.min(8, proof),
      price: Math.min(8, price),
      urgency: Math.min(8, urgency),
      risk: Math.min(8, risk),
      clarity: Math.min(8, clarity),
      objection: Math.min(8, objection)
    };
  }

  function scoreFixes(){
    var pressure = dimensionPressure();
    return fixLibrary.map(function(fix){
      var base = pressure[fix.dim] || 1;
      var bonus = 0;
      if(fix.dim === "objection") bonus += Math.min(3, state.objections.length);
      if(fix.dim === "clarity" && (!val("audience") || !val("cta"))) bonus += 1;
      if(fix.dim === "price" && val("price").length < 4) bonus += .7;
      return Object.assign({}, fix, { score: Math.round((base + bonus) * 10) });
    }).sort(function(a,b){ return b.score - a.score; });
  }

  function healthScore(){
    var good = num(els.proof) + num(els.priceFit) + num(els.urgency) + (6 - num(els.risk));
    return Math.max(0, Math.min(100, Math.round((good / 20) * 100)));
  }

  function rescuePressure(){
    var p = dimensionPressure();
    var total = p.proof + p.price + p.urgency + p.risk + p.clarity + p.objection;
    return Math.max(0, Math.min(100, Math.round((total / 48) * 100)));
  }

  function diagnosisText(health, pressure){
    var p = dimensionPressure();
    var dims = [
      ["proof", p.proof],
      ["price", p.price],
      ["urgency", p.urgency],
      ["risk", p.risk],
      ["clarity", p.clarity],
      ["objections", p.objection]
    ].sort(function(a,b){ return b[1] - a[1]; });

    var lead = "Main weak spots: " + dims.slice(0,3).map(function(x){ return x[0]; }).join(", ") + ". ";
    if(health >= 75) return lead + "The offer is workable. Tighten the highest-pressure fixes before changing the whole offer.";
    if(health >= 50) return lead + "The offer probably needs sharper proof, clearer value framing, or a safer first step.";
    return lead + "The offer needs rescue before more traffic. Fix the promise, proof, CTA, and buyer risk first.";
  }

  function priorityLabel(score){
    if(score >= 65) return {text:"High", cls:"hot"};
    if(score >= 45) return {text:"Medium", cls:"mid"};
    return {text:"Low", cls:"low"};
  }

  function clearNode(node){
    while(node.firstChild) node.removeChild(node.firstChild);
  }

  function makeFixCard(fix, index){
    var card = document.createElement("article");
    card.className = "fix";

    var head = document.createElement("div");
    head.className = "fixHead";

    var title = document.createElement("div");
    title.className = "fixTitle";
    title.textContent = String(index + 1) + ". " + fix.title;

    var pill = document.createElement("div");
    var label = priorityLabel(fix.score);
    pill.className = "pill " + label.cls;
    pill.textContent = label.text + " priority";

    head.appendChild(title);
    head.appendChild(pill);

    var why = document.createElement("p");
    why.textContent = fix.why;

    var action = document.createElement("div");
    action.className = "fixAction";
    action.textContent = fix.action;

    card.appendChild(head);
    card.appendChild(why);
    card.appendChild(action);
    return card;
  }

  function actionPlanText(fixes){
    var lines = [];
    var business = val("business") || "Untitled offer";
    var audience = val("audience") || "target buyer not specified";
    var offer = val("offer") || "Offer not entered yet.";
    var price = val("price") || "Price not specified.";
    var cta = val("cta") || "CTA not specified.";
    var health = healthScore();

    lines.push("Offer Rescue Action Plan");
    lines.push("");
    lines.push("Offer: " + business);
    lines.push("Buyer: " + audience);
    lines.push("Current offer: " + offer);
    lines.push("Price note: " + price);
    lines.push("CTA: " + cta);
    lines.push("Offer health: " + health + "/100");
    lines.push("");
    lines.push("Scores:");
    lines.push("Proof: " + num(els.proof) + "/5");
    lines.push("Price fit: " + num(els.priceFit) + "/5");
    lines.push("Urgency: " + num(els.urgency) + "/5");
    lines.push("Buyer risk: " + num(els.risk) + "/5");
    lines.push("");

    var symptoms = selectedSymptoms().map(function(s){ return s.value.replace(/_/g," "); });
    if(symptoms.length){
      lines.push("Symptoms: " + symptoms.join(", "));
      lines.push("");
    }

    if(state.objections.length){
      lines.push("Top objections:");
      state.objections.forEach(function(o,i){
        lines.push(String(i + 1) + ". " + o);
      });
      lines.push("");
    }

    lines.push("Prioritized fixes:");
    fixes.slice(0,5).forEach(function(fix,i){
      lines.push(String(i + 1) + ". " + fix.title);
      lines.push("   Action: " + fix.action);
    });

    lines.push("");
    lines.push("Rewrite target:");
    lines.push("Make the offer clearer, safer, and easier to act on by adding proof, explaining the price-value link, giving a real reason to act now, and reducing buyer risk.");

    return lines.join("\n");
  }

  function renderObjections(){
    clearNode(els.objectionList);
    state.objections.forEach(function(text, index){
      var item = document.createElement("div");
      item.className = "objectionItem";

      var span = document.createElement("span");
      span.textContent = text;

      var btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = "Remove";
      btn.addEventListener("click", function(){
        state.objections.splice(index,1);
        renderAll();
        save();
      });

      item.appendChild(span);
      item.appendChild(btn);
      els.objectionList.appendChild(item);
    });
  }

  function renderAll(){
    els.proofVal.textContent = String(num(els.proof));
    els.priceFitVal.textContent = String(num(els.priceFit));
    els.urgencyVal.textContent = String(num(els.urgency));
    els.riskVal.textContent = String(num(els.risk));

    var fixes = scoreFixes();
    var topFixes = fixes.slice(0,7);
    clearNode(els.fixList);
    topFixes.forEach(function(fix,index){
      els.fixList.appendChild(makeFixCard(fix,index));
    });

    var health = healthScore();
    var pressure = rescuePressure();

    els.healthNum.textContent = String(health);
    els.riskNum.textContent = String(pressure);
    els.fixNum.textContent = String(topFixes.filter(function(f){ return f.score >= 45; }).length);
    els.objectionNum.textContent = String(state.objections.length);
    els.diagnosis.textContent = diagnosisText(health, pressure);
    els.planBox.textContent = actionPlanText(fixes);
    renderObjections();
  }

  function addObjection(text){
    var clean = String(text || "").trim();
    if(!clean) return;
    var exists = state.objections.some(function(o){ return o.toLowerCase() === clean.toLowerCase(); });
    if(!exists) state.objections.push(clean);
    els.objectionInput.value = "";
    renderAll();
    save();
  }

  function showToast(msg){
    els.toast.textContent = msg;
    els.toast.classList.add("show");
    setTimeout(function(){ els.toast.classList.remove("show"); }, 1400);
  }

  function copyText(text){
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){ showToast("Copied"); }).catch(function(){ fallbackCopy(text); });
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text){
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly","");
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand("copy"); showToast("Copied"); }
    catch(e){ showToast("Copy failed"); }
    document.body.removeChild(ta);
  }

  function downloadFile(filename, content, type){
    var blob = new Blob([content], {type:type});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(function(){
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 0);
  }

  function collectData(){
    return {
      business: els.business.value,
      audience: els.audience.value,
      offer: els.offer.value,
      price: els.price.value,
      cta: els.cta.value,
      objections: state.objections.slice(),
      scores: {
        proof: els.proof.value,
        priceFit: els.priceFit.value,
        urgency: els.urgency.value,
        risk: els.risk.value
      },
      symptoms: selectedSymptoms().map(function(s){ return s.value; })
    };
  }

  function applyData(data){
    if(!data) return;
    els.business.value = data.business || "";
    els.audience.value = data.audience || "";
    els.offer.value = data.offer || "";
    els.price.value = data.price || "";
    els.cta.value = data.cta || "";
    state.objections = Array.isArray(data.objections) ? data.objections : [];

    if(data.scores){
      els.proof.value = data.scores.proof || 3;
      els.priceFit.value = data.scores.priceFit || 3;
      els.urgency.value = data.scores.urgency || 3;
      els.risk.value = data.scores.risk || 3;
    }

    var symptomSet = new Set(data.symptoms || []);
    Array.prototype.slice.call(document.querySelectorAll("#symptomChips input")).forEach(function(input){
      input.checked = symptomSet.has(input.value);
    });
  }

  function save(){
    try{
      localStorage.setItem("offerRescueDesk:v1", JSON.stringify(collectData()));
    }catch(e){}
  }

  function load(){
    try{
      var raw = localStorage.getItem("offerRescueDesk:v1");
      if(raw) applyData(JSON.parse(raw));
    }catch(e){}
  }

  function resetAll(){
    if(!confirm("Clear this offer rescue desk?")) return;
    localStorage.removeItem("offerRescueDesk:v1");
    state.objections = [];
    ["business","audience","offer","price","cta","objectionInput"].forEach(function(id){
      document.getElementById(id).value = "";
    });
    els.proof.value = 3;
    els.priceFit.value = 3;
    els.urgency.value = 3;
    els.risk.value = 3;
    Array.prototype.slice.call(document.querySelectorAll("#symptomChips input")).forEach(function(input){
      input.checked = false;
    });
    renderAll();
    showToast("Reset");
  }

  document.getElementById("scoreBtn").addEventListener("click", function(){
    renderAll();
    save();
    showToast("Scored");
  });

  document.getElementById("copyPlanBtn").addEventListener("click", function(){
    renderAll();
    copyText(els.planBox.textContent);
  });

  document.getElementById("exportTxtBtn").addEventListener("click", function(){
    renderAll();
    downloadFile("offer-rescue-action-plan.txt", els.planBox.textContent, "text/plain");
  });

  document.getElementById("exportJsonBtn").addEventListener("click", function(){
    renderAll();
    var exportData = collectData();
    exportData.generatedPlan = els.planBox.textContent;
    exportData.generatedAt = new Date().toISOString();
    downloadFile("offer-rescue-desk.json", JSON.stringify(exportData,null,2), "application/json");
  });

  document.getElementById("resetBtn").addEventListener("click", resetAll);

  document.getElementById("addObjectionBtn").addEventListener("click", function(){
    addObjection(els.objectionInput.value);
  });

  els.objectionInput.addEventListener("keydown", function(e){
    if(e.key === "Enter"){
      e.preventDefault();
      addObjection(els.objectionInput.value);
    }
  });

  Array.prototype.slice.call(document.querySelectorAll("[data-objection]")).forEach(function(btn){
    btn.addEventListener("click", function(){
      addObjection(btn.getAttribute("data-objection"));
    });
  });

  Array.prototype.slice.call(document.querySelectorAll("input, textarea")).forEach(function(input){
    input.addEventListener("input", function(){
      renderAll();
      save();
    });
    input.addEventListener("change", function(){
      renderAll();
      save();
    });
  });

  Array.prototype.slice.call(document.querySelectorAll("[data-view]")).forEach(function(btn){
    btn.addEventListener("click", function(){
      var view = btn.getAttribute("data-view");
      Array.prototype.slice.call(document.querySelectorAll("[data-view]")).forEach(function(b){
        b.classList.toggle("active", b === btn);
      });
      document.getElementById("fixesView").classList.toggle("hidden", view !== "fixes");
      document.getElementById("planView").classList.toggle("hidden", view !== "plan");
    });
  });

  load();
  renderAll();
})();
</script>
</body>
</html>
